  }
  var payload = {
    name:name, oneliner:oneliner,
    desc:document.getElementById('fDesc').value.trim(),
    stage:document.getElementById('fStage').value,
    sector:document.getElementById('fSector').value,
    url:document.getElementById('fUrl').value.trim(),
    email:email,
    founder:document.getElementById('fFounder').value.trim()
  };
  fetch(API_BASE + '/startups', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify(payload)
  })
    .then(function(r){return r.json();})
    .then(function(data){
      if(data.error){
        showToast(data.error);
        return;
      }
      STARTUPS.push(data.startup);
      if(data.edit_token){ saveEditToken(data.startup.id, data.edit_token); }
      currentFilter = '';
      document.querySelectorAll('.chip').forEach(function(c,i){c.classList.toggle('on', i===0);});
      renderStartups();
      ['fName','fOneliner','fDesc','fUrl','fEmail','fFounder'].forEach(function(id){document.getElementById(id).value='';});
      showToast(name + ' is now listed 🎉');
      if(data.edit_token){
        showEditLink(data.startup.id, data.edit_token);
        document.getElementById('editLinkBox').scrollIntoView({behavior:'smooth'});
      } else {
        document.getElementById('directory').scrollIntoView({behavior:'smooth'});
      }
    })
    .catch(function(){
      showToast('Could not submit — try again.');
    });
}

var toastTimer;
function showToast(msg){
  var t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(function(){t.classList.remove('show');}, 2600);
}

